}
function sc630_dashboard_stats(): array { $tid=sc630_tid();$s=[];$s['citizen_requests']=sc630_safe_count('municipal_requests_v630','tenant_id=?',[$tid]);$s['open_requests']=sc630_safe_count('municipal_requests_v630',"tenant_id=? AND status NOT IN ('resolved','closed','rejected')",[$tid]);$s['wallets']=sc630_safe_count('citizen_wallet_accounts_v630','tenant_id=?',[$tid]);try{$q=db()->prepare('SELECT COALESCE(SUM(balance),0),COALESCE(SUM(loyalty_points),0) FROM citizen_wallet_accounts_v630 WHERE tenant_id=?');$q->execute([$tid]);$r=$q->fetch(PDO::FETCH_NUM)?:[0,0];$s['wallet_balance']=(float)$r[0];$s['points']=(int)$r[1];}catch(Throwable $e){$s['wallet_balance']=0;$s['points']=0;}$s['notifications']=sc630_safe_count('smart_notifications_v630','tenant_id=?',[$tid]);$s['assistant_messages']=sc630_safe_count('smart_assistant_messages_v630','tenant_id=?',[$tid]);return $s; }

function sc630_search_table(string $table,string $titleCol,array $bodyCols,string $urlPrefix,string $type,string $q,int $limit=5,?string $statusWhere=null): array { if(!sc630_table($table))return [];$cols=sc630_columns($table);if(!isset($cols[$titleCol]))return [];$searchCols=array_values(array_filter(array_merge([$titleCol],$bodyCols),fn($x)=>isset($cols[$x])));if(!$searchCols)return [];$where=[];$p=[];foreach($searchCols as $c){$where[]='`'.$c.'` LIKE ?';$p[]='%'.$q.'%';}$tenant='';if(isset($cols['tenant_id'])){$tenant=' AND (`tenant_id`=0 OR `tenant_id`=?)';$p[]=sc630_tid();}$status=$statusWhere?' AND '.$statusWhere:'';$idCol=isset($cols['slug'])?'slug':'id';try{$sql='SELECT `'.$idCol.'` ref,`'.$titleCol.'` title'.(isset($cols['area'])?',`area`':'').(isset($cols['address'])?',`address`':'').' FROM `'.$table.'` WHERE ('.implode(' OR ',$where).')'.$tenant.$status.' LIMIT '.max(1,min(10,$limit));$st=db()->prepare($sql);$st->execute($p);$out=[];foreach($st->fetchAll()?:[] as $r){$ref=(string)$r['ref'];$url=$urlPrefix.(str_contains($urlPrefix,'?')?'':'?').(str_ends_with($urlPrefix,'=')?'':'id=').rawurlencode($ref);$out[]=['type'=>$type,'title'=>$r['title'],'subtitle'=>$r['area']??$r['address']??'','url'=>$url];}return $out;}catch(Throwable $e){return [];} }
function sc630_super_search(string $q,int $limit=24): array { $q=trim($q);if(mb_strlen($q)<2)return [];$all=[];$all=array_merge($all,sc630_search_table('businesses','name',['address','area'],'/business.php?','Business',$q,4,"status='active'"));$all=array_merge($all,sc630_search_table('health_doctors_v580','display_name',['qualification','bio'],'/doctor-profile.php?slug=','Doctor',$q,4,"approval_status='approved'"));$all=array_merge($all,sc630_search_table('blood_banks_v570','name',['address','area'],'/blood-bank.php?bank=','Blood Bank',$q,3,"status='active'"));$all=array_merge($all,sc630_search_table('health_pharmacies_v590','name',['address','area'],'/pharmacy.php?id=','Pharmacy',$q,3,"status='active'"));$all=array_merge($all,sc630_search_table('health_labs_v590','name',['address','area'],'/lab.php?id=','Lab',$q,3,"status='active'"));$all=array_merge($all,sc630_search_table('store_products','title',['short_description','description'],'/product.php?slug=','Product',$q,5,"status='published'"));$all=array_merge($all,sc630_search_table('edu_institutions_v700','name',['tagline','description','area'],'/institution.php?id=','Education',$q,4,"status='active'"));$all=array_merge($all,sc630_search_table('tourism_hotels_v700','name',['description','area'],'/hotel.php?id=','Hotel',$q,4,"status='active'"));$all=array_merge($all,sc630_search_table('tourism_restaurants_v700','name',['cuisine','area'],'/restaurant.php?id=','Restaurant',$q,4,"status='active'"));$all=array_merge($all,sc630_search_table('tourism_attractions_v700','name',['category','description','area'],'/tourism.php?place=','Tourism',$q,4,"status='active'"));return array_slice($all,0,max(1,min(50,$limit))); }

function sc630_detect_intent(string $text): string { $t=mb_strtolower($text);$sets=['emergency'=>['emergency','ambulance','rescue','حادث','ایمرجنسی'],'doctor'=>['doctor','appointment','checkup','consult','ڈاکٹر'],'blood'=>['blood','donor','donation','خون'],'pharmacy'=>['pharmacy','medicine','فارمیسی'],'lab'=>['lab','test','report','لیب'],'education'=>['school','college','academy','course','admission','education','تعلیم','سکول'],'transport'=>['bus','transport','ride','taxi','rickshaw','delivery','travel','سفر'],'tourism'=>['hotel','restaurant','tourism','tour','visit','stay','booking','ہوٹل'],'property'=>['property','house','plot','rent','گھر','پلاٹ'],'marketplace'=>['product','shop','buy','order','deal','shopping'],'municipal'=>['complaint','street','road','waste','water','light','municipal','شکایت'],'wallet'=>['wallet','points','loyalty','balance','earning'],'jobs'=>['job','vacancy','career','نوکری'],'events'=>['event','festival','program']];foreach($sets as $intent=>$words)foreach($words as $w)if(mb_strpos($t,$w)!==false)return $intent;return 'general'; }
function sc630_assistant_reply(string $text,?array $u=null): array {
    $intent=sc630_detect_intent($text);$em=sc630_emergency_number();$links=[];$reply='I can help you navigate ShahkotPK services and find the right module.';
    switch($intent){
      case 'emergency':$reply='For a life-threatening emergency, contact local emergency services now. The portal can also open the ambulance and emergency service pages, but a web request should not delay emergency help.';$links=[['Call '.$em,'tel:'.preg_replace('/[^0-9+]/','',$em)],['Ambulance','/ambulance.php'],['Emergency Help','/health-network.php']];break;
      case 'doctor':$reply='You can find city doctors, check availability and book online or in-person appointments from Doctor Online.';$links=[['Find Doctor','/find-doctor.php'],['My Health','/my-health.php']];break;
      case 'blood':$reply='Use Blood Bank to check participating banks, register as a donor or submit a blood request. Medical suitability and matching remain with authorized blood-bank staff.';$links=[['Blood Bank','/blood-bank.php'],['Donate Blood','/blood-donate.php'],['Request Blood','/blood-request.php']];break;
      case 'pharmacy':$reply='Browse the verified pharmacy network and submit medicine order requests. Prescription-required items remain subject to pharmacy verification.';$links=[['Pharmacies','/pharmacies.php'],['My Health Network','/health-network-account.php']];break;
      case 'lab':$reply='Browse diagnostic labs, published tests and available home sample collection, then manage bookings and reports privately.';$links=[['Diagnostic Labs','/labs.php'],['My Health Network','/health-network-account.php']];break;
      case 'education':$reply='Use the Education platform to discover schools, colleges and academies, compare programs and submit admission applications online.';$links=[['Education','/education.php'],['My Education','/education-account.php']];break;
      case 'transport':$reply='Use the Transport network for scheduled trips, ride requests, rickshaws, taxis and city delivery.';$links=[['Transport','/transport.php'],['Request Ride','/ride.php'],['My Travel','/transport-account.php']];break;
      case 'tourism':$reply='Explore local attractions, hotels, restaurants and tour packages, then manage bookings from your tourism dashboard.';$links=[['Tourism','/tourism.php'],['My Bookings','/tourism-account.php']];break;
      case 'property':$reply='Property Marketplace Pro lets you search, compare, save listings and request visits or inquiries.';$links=[['Property','/property.php'],['My Properties','/my-properties.php']];break;
      case 'marketplace':$reply='Use the marketplace to find products, deals, auctions and seller stores, and track your orders from your citizen dashboard.';$links=[['Marketplace','/shop.php'],['My Orders','/my-orders.php'],['Auctions','/auctions.php']];break;
      case 'municipal':$reply='You can submit a non-emergency city complaint or service request and track every status update with a reference number.';$links=[['City Services','/complaints.php'],['Citizen Dashboard','/citizen.php']];break;
      case 'wallet':$reply='Your Citizen Wallet keeps portal credits and loyalty points in an auditable ledger. You can view activity and redeem eligible loyalty points when enabled.';$links=[['Wallet & Loyalty','/wallet.php'],['Citizen Dashboard','/citizen.php']];break;
      case 'jobs':$reply='Browse current local opportunities from the ShahkotPK Jobs section.';$links=[['Jobs','/jobs.php']];break;
      case 'events':$reply='Browse current city events and activities from the Events section.';$links=[['Events','/events.php']];break;
      default:$hits=sc630_super_search($text,6);if($hits){$reply='I found a few relevant ShahkotPK results. Choose one below or refine your search.';foreach($hits as $h)$links[]=[$h['type'].' · '.$h['title'],$h['url']];}else{$links=[['Citizen Dashboard','/citizen.php'],['Super Search','/smart-assistant.php'],['City Services','/complaints.php'],['Healthcare','/health-network.php']];}
    }
    $session=session_id()?:bin2hex(random_bytes(8));try{$uid=$u?(int)$u['id']:null;$q=db()->prepare("INSERT INTO smart_assistant_messages_v630(tenant_id,user_id,session_key,role,intent,message,created_at) VALUES(?,?,?,'user',?,?,NOW()),(?,?,?,'assistant',?,?,NOW())");$q->execute([sc630_tid(),$uid,$session,$intent,$text,sc630_tid(),$uid,$session,$intent,$reply]);}catch(Throwable $e){}sc630_track('assistant','message','intent',null,['intent'=>$intent]);return ['intent'=>$intent,'reply'=>$reply,'links'=>$links];
}
function sc630_recommendations(?int $uid=null): array { $scores=[];if($uid){try{$q=db()->prepare('SELECT module,COUNT(*) n FROM smart_recommendation_events_v630 WHERE tenant_id=? AND user_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 60 DAY) GROUP BY module ORDER BY n DESC LIMIT 5');$q->execute([sc630_tid(),$uid]);foreach($q->fetchAll()?:[] as $r)$scores[$r['module']]=(int)$r['n'];}catch(Throwable $e){}}$catalog=['education'=>['Education','Schools, academies, programs and admissions','/education.php','▤'],'transport'=>['Transport','Trips, rides and city delivery','/transport.php','↔'],'tourism'=>['Tourism','Hotels, restaurants and city experiences','/tourism.php','✦'],'health'=>['Doctor Online','Book or manage a consultation','/doctor-online.php','✚'],'marketplace'=>['Marketplace','Shop local products and deals','/shop.php','◇'],'property'=>['Property','Explore homes, plots and commercial listings','/property.php','⌂'],'municipal'=>['City Services','Submit and track a city request','/complaints.php','◫'],'blood'=>['Blood Bank','Donation and blood request services','/blood-bank.php','♥'],'healthnet'=>['Healthcare Network','Pharmacy, labs and ambulance','/health-network.php','✦'],'jobs'=>['Jobs','Discover local opportunities','/jobs.php','▣']];$order=array_keys($scores);foreach(array_keys($catalog) as $k)if(!in_array($k,$order,true))$order[]=$k;$out=[];foreach(array_slice($order,0,6) as $k)if(isset($catalog[$k]))$out[]=['module'=>$k,'title'=>$catalog[$k][0],'text'=>$catalog[$k][1],'url'=>$catalog[$k][2],'icon'=>$catalog[$k][3]];return $out; }

function sc630_staff_permissions(int $uid): array { if($uid<1||!sc630_table('smart_city_staff_v630'))return [];try{$tid=sc630_tid();$q=db()->prepare('SELECT access_role,permissions_json FROM smart_city_staff_v630 WHERE user_id=? AND status=1 AND tenant_id=?');$q->execute([$uid,$tid]);$roles=['smartcity_admin'=>['smartcity.dashboard','smartcity.municipal.manage','smartcity.wallet.manage','smartcity.loyalty.manage','smartcity.notifications.manage','smartcity.ai.manage','smartcity.staff.manage','smartcity.analytics','smartcity.settings'],'municipal_manager'=>['smartcity.dashboard','smartcity.municipal.manage','smartcity.analytics'],'municipal_officer'=>['smartcity.dashboard','smartcity.municipal.manage'],'wallet_manager'=>['smartcity.dashboard','smartcity.wallet.manage','smartcity.loyalty.manage','smartcity.analytics'],'citizen_service'=>['smartcity.dashboard','smartcity.municipal.manage','smartcity.notifications.manage'],'ai_manager'=>['smartcity.dashboard','smartcity.ai.manage','smartcity.analytics'],'analyst'=>['smartcity.dashboard','smartcity.analytics']];$out=[];foreach($q->fetchAll()?:[] as $r){$p=json_decode((string)($r['permissions_json']??''),true);if(!is_array($p)||!$p)$p=$roles[$r['access_role']]??$roles['analyst'];$out=array_merge($out,$p);}return array_values(array_unique($out));}catch(Throwable $e){return [];} }

